 add('CQ',stem,'উপপ্রশ্নভিত্তিক নমুনা উত্তর; স্বাধীন শিক্ষক যাচাই বাকি।',f,p,difficulty='HARD',parts=[dict(label=label,question=q,solution=a,marks=n) for n,(label,(q,a)) in enumerate(zip('কখগঘ',parts),1)])
